/**
 * The `docfx-net` adapter: .NET API references generated by DocFX. The symbol index is the
 * xrefmap of each API set named in the registry; the table of contents next to the pages
 * adds what an xrefmap lacks, the kind of each type, where the site's DocFX version states it. Pages are server-rendered HTML, one per
 * type and one per member.
 */
import type { McpDocError } from '../../core/errors.js';
import { toMcpDocError } from '../../core/errors.js';
import type { BoundSource, Ctx, SourceAdapter } from '../../core/ports.js';
import type { CatalogRecord } from '../../core/types.js';
import {
  assertLive,
  continueWithout,
  indexRequest,
  probeSource,
  readHtmlPage,
  recordOf,
  siteIndexEnabled,
  symbolTarget,
  unusableIndex,
} from './dartdoc.js';
import { parseXrefmap, type XrefEntry } from './xrefmap.js';

/** An xrefmap and its table of contents are two requests; this many API sets are read. */
const MAX_XREFMAPS = 3;

/** Symbol kind by documentation-id prefix; `T` is refined from the table of contents. */
const KINDS: ReadonlyMap<string, string> = new Map([
  ['N', 'namespace'],
  ['T', 'type'],
  ['M', 'method'],
  ['P', 'property'],
  ['F', 'field'],
  ['E', 'event'],
]);

/** `QueryAsync<T>(String)` gives `QueryAsync`. */
function bareName(name: string): string {
  return name.replace(/[(<[].*$/s, '');
}

/**
 * Catalogue records of one xrefmap.
 *
 * - Overload groups (`Overload:` ids) are skipped: their members are listed one by one.
 * - An entry without a documentation id is a page of the reference, not a symbol.
 * - A member's parent is its uid without the parameter list and the last segment; a nested
 *   type is a member of its outer type.
 * - Qualified names drop the generic arity (`` List`1 `` becomes `List`), as in code.
 * - `typeKinds` maps a uid to the kind the table of contents states (`class`, `enum`, ...).
 * - Entries whose uid is in `seen` are skipped and every kept uid is added to it, so a
 *   second API set only contributes what the first one lacks.
 */
export function xrefRecords(
  src: BoundSource,
  entries: readonly XrefEntry[],
  typeKinds: ReadonlyMap<string, string> = new Map(),
  seen = new Set<string>(),
  platform?: string,
): CatalogRecord[] {
  const base = src.url();
  const types = new Set(
    entries.filter((entry) => entry.commentId?.startsWith('T:')).map((entry) => entry.uid),
  );
  const records = new Map<string, CatalogRecord>();
  for (const entry of entries) {
    const prefix = entry.commentId?.split(':', 1)[0] ?? '';
    if (entry.href === undefined || prefix === 'Overload' || seen.has(entry.uid)) continue;
    const ref = new URL(entry.href, base).href;
    if (!ref.startsWith(base) || records.has(ref)) continue;
    seen.add(entry.uid);
    const title = entry.nameWithType ?? entry.name ?? entry.uid;
    if (!KINDS.has(prefix)) {
      // A conceptual page of the site has a uid but documents no symbol.
      records.set(ref, recordOf(src, ref, title, { locator: { uid: entry.uid }, platform }));
      continue;
    }

    const path = entry.uid.replace(/\(.*$/s, '');
    const cut = path.lastIndexOf('.');
    const container = cut < 0 ? '' : path.slice(0, cut);
    const member = prefix !== 'T' && prefix !== 'N';
    const owned = container !== '' && (member || (prefix === 'T' && types.has(container)));
    const parent = owned ? container.replace(/`+\d+/g, '') : undefined;
    const symbol = bareName(entry.name ?? path.slice(cut + 1));
    const constructor = prefix === 'M' && path.endsWith('#ctor');
    records.set(
      ref,
      recordOf(src, ref, title, {
        symbol,
        qualified:
          member && parent !== undefined ? `${parent}.${symbol}` : path.replace(/`+\d+/g, ''),
        symbolKind: typeKinds.get(entry.uid) ?? (constructor ? 'constructor' : KINDS.get(prefix)),
        parent,
        breadcrumb: prefix === 'N' ? [] : [parent ?? container],
        locator: { uid: entry.uid },
        platform,
      }),
    );
  }
  return [...records.values()];
}

interface TocNode {
  topicUid?: unknown;
  type?: unknown;
  items?: unknown;
}

/** Kind of every topic a DocFX `toc.json` lists (`Class`, `Struct`, `Enum`, ... in lower case). */
export function tocKinds(toc: unknown): Map<string, string> {
  const kinds = new Map<string, string>();
  const stack: unknown[] = [toc];
  for (let node = stack.pop(); node !== undefined; node = stack.pop()) {
    if (Array.isArray(node)) {
      stack.push(...(node as unknown[]));
      continue;
    }
    if (typeof node !== 'object' || node === null) continue;
    const { topicUid, type, items } = node as TocNode;
    if (typeof topicUid === 'string' && typeof type === 'string' && type !== '') {
      kinds.set(topicUid, type.toLowerCase());
    }
    if (items !== undefined) stack.push(items);
  }
  return kinds;
}

/**
 * The table of contents of the API set an xrefmap describes: `toc.json` in the directory
 * that holds the set (`api/net/` for `api/net/<assembly>/<page>.html`).
 */
function tocPath(entries: readonly XrefEntry[]): string | undefined {
  const href = entries.find((entry) => entry.href !== undefined)?.href;
  if (href === undefined || /^[a-z][a-z0-9+.-]*:/i.test(href)) return undefined;
  const segments = href.replace(/#.*$/, '').split('/');
  const directory = segments.length >= 3 ? segments.slice(0, 2) : segments.slice(0, -1);
  return [...directory, 'toc.json'].join('/');
}

async function readTocKinds(
  ctx: Ctx,
  src: BoundSource,
  entries: readonly XrefEntry[],
): Promise<Map<string, string>> {
  const path = tocPath(entries);
  if (path === undefined) return new Map();
  try {
    const { data } = await ctx.http.getJson(indexRequest(src, src.url(path), 'json'));
    return tocKinds(data);
  } catch (error) {
    // Without it every type is still listed, as kind `type`.
    continueWithout(ctx, src, error, `The table of contents ${path}`);
    return new Map();
  }
}

/** The API set an xrefmap is named after: `netwin.xrefmap.yml` gives `netwin`. */
function apiSet(file: string): string | undefined {
  const name = file.replace(/^.*\//, '').replace(/\.?xrefmap\.ya?ml$/i, '');
  return name === '' ? undefined : name;
}

/**
 * `docfx-net`: for each configured xrefmap, one request for the file and one for the table
 * of contents of its API set. The first xrefmap is the platform-neutral API; later ones add
 * only the symbols it lacks (UI controls), tagged with their API set as `platform`.
 */
export const docfxNetAdapter: SourceAdapter<'docfx-net'> = {
  type: 'docfx-net',
  maxEnumerateRequests: MAX_XREFMAPS * 2,

  async enumerate(ctx, src) {
    assertLive(src, src.url());
    if (!siteIndexEnabled(ctx, src)) return [];
    const files = src.source.config.xrefmaps;
    if (files.length > MAX_XREFMAPS) {
      ctx.logger.warn('More xrefmaps are configured than one enumeration reads', {
        product: src.product.id,
        source: src.source.id,
        configured: files.length,
        read: MAX_XREFMAPS,
      });
    }
    const seen = new Set<string>();
    const records = new Map<string, CatalogRecord>();
    let firstFailure: McpDocError | undefined;
    for (const [position, file] of files.slice(0, MAX_XREFMAPS).entries()) {
      const url = src.url(file);
      try {
        const res = await ctx.http.get(indexRequest(src, url, 'yaml'));
        const entries = parseXrefmap(res.text);
        if (entries.length === 0) throw unusableIndex(url, 'The xrefmap has no references');
        const kinds = await readTocKinds(ctx, src, entries);
        const platform = position === 0 ? undefined : apiSet(file);
        for (const record of xrefRecords(src, entries, kinds, seen, platform)) {
          if (!records.has(record.ref)) records.set(record.ref, record);
        }
      } catch (error) {
        firstFailure ??= toMcpDocError(error);
        continueWithout(ctx, src, error, `The xrefmap ${file}`);
      }
    }
    if (records.size > 0) return [...records.values()];
    throw (
      firstFailure ?? unusableIndex(src.url(), 'No xrefmap entry points to a page of this source')
    );
  },

  read: (ctx, src, target) => readHtmlPage(ctx, src, target, 'docfx-net'),
  symbol: (ctx, src, record, detail) =>
    readHtmlPage(ctx, src, symbolTarget(record, detail), 'docfx-net'),
  probe: (ctx, src) =>
    probeSource(ctx, src, {
      count: (text) => (/^references:/m.test(text) ? parseXrefmap(text).length : undefined),
    }),
};
